descriptor.templateCss:
.kvh-wrap{height:100%;container-type:inline-size;font-family:'Mulish',Roboto,'Helvetica Neue',sans-serif;overflow:hidden}
.kvh-root{height:100%;box-sizing:border-box;display:grid;grid-template-columns:minmax(260px,1fr) minmax(0,3.2fr);gap:12px;color:#24302A;-webkit-font-smoothing:antialiased}
.kvh-root *{box-sizing:border-box}
.kvh-ficha{background:#4F6B5C;color:#fff;border-radius:12px;padding:14px 18px;display:flex;flex-direction:column;gap:10px;min-width:0;min-height:0;overflow:hidden;box-shadow:0 1px 4px rgba(36,48,42,.15)}
.kvh-fhead{display:flex;flex-direction:column;gap:3px}
.kvh-eyebrow{font-size:11px;font-weight:800;letter-spacing:1.6px;text-transform:uppercase;color:#E2EBE4}
.kvh-title{margin:0;font-family:'Playfair Display',Georgia,serif;font-size:24px;font-weight:700;line-height:1.15;color:#fff;overflow-wrap:anywhere}
.kvh-rows{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px 16px}
.kvh-row{display:flex;flex-direction:column;gap:1px;min-width:0}
.kvh-rl{font-size:10px;font-weight:800;letter-spacing:1px;text-transform:uppercase;color:#D3DFD6}
.kvh-rv{font-size:14px;font-weight:700;color:#fff;overflow-wrap:anywhere;line-height:1.25}
.kvh-last{margin-top:auto;align-self:flex-start;display:inline-flex;align-items:center;gap:7px;font-size:12px;font-weight:700;background:rgba(255,255,255,.14);border-radius:999px;padding:5px 12px;color:#fff;white-space:nowrap}
.kvh-ldot{width:7px;height:7px;border-radius:50%;background:#C8E05A;box-shadow:0 0 0 3px rgba(200,224,90,.25)}
.kvh-ldot.old{background:#F0B37E;box-shadow:0 0 0 3px rgba(240,179,126,.25)}
.kvh-kpis{display:grid;gap:10px;min-width:0;min-height:0}
.kvh-kpi{background:#fff;border:1px solid #DCE3DA;border-radius:12px;padding:10px 14px;display:flex;flex-direction:column;justify-content:space-between;gap:4px;min-width:0;min-height:0;overflow:hidden;box-shadow:0 1px 3px rgba(36,48,42,.08)}
.kvh-ktop{display:flex;align-items:center;gap:8px;min-width:0}
.kvh-ico{width:28px;height:28px;border-radius:8px;display:inline-flex;align-items:center;justify-content:center;flex:0 0 auto}
.kvh-ico svg{width:17px;height:17px}
.kvh-kl{font-size:13px;font-weight:700;color:#3D3833;line-height:1.2;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
.kvh-kv{font-size:28px;font-weight:800;line-height:1.05;color:#24302A;white-space:nowrap;font-variant-numeric:tabular-nums;letter-spacing:-.3px}
.kvh-ku{font-size:13px;font-weight:700;color:#5A534D;margin-left:5px;letter-spacing:0}
.kvh-kbot{display:flex;align-items:flex-end;justify-content:space-between;gap:8px;min-height:24px}
.kvh-kd{display:flex;align-items:center;gap:5px;min-width:0;white-space:nowrap}
.kvh-delta{font-size:11px;font-weight:800;border-radius:999px;padding:2px 8px;white-space:nowrap}
.kvh-delta.up{background:#E7EEE3;color:#2E4A33}
.kvh-delta.down{background:#F8E9DE;color:#8A3F12}
.kvh-delta.eq{background:#EEF2EC;color:#4A443F}
.kvh-vs{font-size:11px;color:#5A534D;white-space:nowrap}
.kvh-sp{position:relative;width:40%;max-width:120px;height:24px;flex:0 1 auto}
.kvh-spark{width:100%;height:24px;display:block}
.kvh-sdot{position:absolute;width:5px;height:5px;border-radius:50%;transform:translate(50%,-50%)}
/* Ajuste automático cuando el widget es bajo */
.kvh-wrap.dense .kvh-kpi{padding:7px 12px;gap:2px}
.kvh-wrap.dense .kvh-kv{font-size:22px}
.kvh-wrap.dense .kvh-ico{width:24px;height:24px}
.kvh-wrap.dense .kvh-ico svg{width:15px;height:15px}
.kvh-wrap.dense .kvh-kbot{min-height:20px}
.kvh-wrap.dense .kvh-sp,.kvh-wrap.dense .kvh-spark{height:20px}
.kvh-wrap.dense .kvh-ficha{padding:10px 16px;gap:6px}
.kvh-wrap.dense .kvh-title{font-size:20px}
.kvh-wrap.denser .kvh-kbot{display:none}
.kvh-wrap.denser .kvh-rows{gap:4px 14px}
.kvh-wrap.denser .kvh-last{padding:3px 10px}
@container (max-width: 1100px){
  .kvh-kv{font-size:24px}
}
@container (max-width: 820px){
  .kvh-root{grid-template-columns:minmax(0,1fr);height:auto}
  .kvh-kpis{grid-template-columns:repeat(2,minmax(0,1fr))!important;grid-template-rows:none!important}
  .kvh-wrap{overflow:auto}
}

descriptor.controllerScript:
// Kuvio · Ficha e indicadores del sensor
// Ajuste: settings.perfil = lisimetro | agroclimatica | sonda4e | meteo | electrico

var DAY = 86400000;
var MES = ['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'];

var ICO = {
  agua: '<path d="M12 3.5s6 6.4 6 10.9a6 6 0 0 1-12 0C6 9.9 12 3.5 12 3.5z"/>',
  temp: '<path d="M14 14.8V5a2 2 0 0 0-4 0v9.8a4 4 0 1 0 4 0z"/><path d="M12 9v7"/>',
  nivel: '<path d="M4 20h16"/><path d="M7 16V10M12 16V5M17 16v-4"/>',
  rayo: '<path d="M13 3 5 13h6l-1 8 8-10h-6l1-8z"/>',
  onda: '<path d="M3 12c2-4 4-4 6 0s4 4 6 0 4-4 6 0"/>',
  frio: '<path d="M12 3v18M4.2 7.5l15.6 9M4.2 16.5l15.6-9"/>',
  sol: '<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>',
  brote: '<path d="M12 21v-8"/><path d="M12 13c0-4 3-6.5 7.5-6.5 0 4-3 6.5-7.5 6.5z"/><path d="M12 13c0-3.2-2.4-5.5-6.5-5.5 0 3.2 2.4 5.5 6.5 5.5z"/>',
  reloj: '<circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3 2"/>',
  delta: '<path d="M12 4.5 20.5 19h-17z"/>',
  curva: '<path d="M4 19h16"/><path d="M5 15l4.5-4.5 3.5 3.5L19 8"/>',
  medidor: '<path d="M4 17a8 8 0 0 1 16 0"/><path d="M12 17l4-5"/>',
  gota_mas: '<path d="M10 4s5 5.3 5 9.1A5 5 0 0 1 5 13.1C5 9.3 10 4 10 4z"/><path d="M19 6v6M16 9h6"/>'
};
var TONO = {
  agua: ['#E3ECF6', '#2F5D8A'], temp: ['#F8E9DE', '#B4561B'], energia: ['#E7EEE3', '#33513A'],
  clima: ['#F4EED6', '#7A5F0C'], suelo: ['#EDF1DC', '#5C7410']
};

var PERFILES = {
  lisimetro: {eyebrow: 'Lisímetro', ficha: [{label: 'Finca', key: 'finca'}], kpis: [
    {key: 'cva_30', label: 'Humedad 30 cm', unit: '%', dec: 1, ico: 'agua', tono: 'agua'},
    {key: 'deposito_nivel_mm', label: 'Nivel de depósito', unit: 'mm', dec: 0, ico: 'nivel', tono: 'agua'},
    {key: 'drenaje_lm2', label: 'Drenaje', unit: 'L/m²', dec: 1, ico: 'gota_mas', tono: 'agua'},
    {key: 'drenaje_ce_uscm', label: 'CE del drenaje', unit: 'µS/cm', dec: 0, ico: 'onda', tono: 'suelo'}]},
  agroclimatica: {eyebrow: 'Estación agroclimática', ficha: [{label: 'Zona', key: 'zona'}, {label: 'SIGPAC', key: 'sigpac'}, {label: 'Cultivo', key: 'cultivo'}, {label: 'Superficie', key: 'hectareas', unit: 'ha', dec: 1}], kpis: [
    {key: 'irrigation_1_1', label: 'Estado de riego', unit: '', dec: 0, ico: 'brote', tono: 'agua'},
    {key: 'soil_ce_4', label: 'CE del suelo', unit: 'dS/m', dec: 2, ico: 'onda', tono: 'suelo'},
    {key: 'agroan_deltat', label: 'Delta T', unit: '°C', dec: 1, ico: 'delta', tono: 'temp'},
    {key: 'agroan_coldhours', label: 'Horas de frío', unit: 'h', dec: 0, ico: 'frio', tono: 'agua'},
    {key: 'agroan_frozenhours', label: 'Horas de helada', unit: 'h', dec: 0, ico: 'frio', tono: 'clima'},
    {key: 'agroan_hothours', label: 'Horas de calor', unit: 'h', dec: 0, ico: 'sol', tono: 'temp'}]},
  sonda4e: {eyebrow: 'Sonda 4eGrowth', ficha: [{label: 'Finca', key: 'zona'}, {label: 'Parcela', key: 'sigpac'}, {label: 'Cultivo', key: 'cultivo'}, {label: 'Superficie', key: 'hectareas', unit: 'ha', dec: 1}], kpis: [
    {key: 'hum_suelo_media', label: 'Humedad media', unit: '%', dec: 1, ico: 'agua', tono: 'agua'},
    {key: 'hum_suelo_30cm', label: 'Humedad 30 cm', unit: '%', dec: 1, ico: 'agua', tono: 'agua'},
    {key: 'temp_suelo_30cm', label: 'Temp. suelo 30 cm', unit: '°C', dec: 1, ico: 'temp', tono: 'temp'},
    {key: 'ce_suelo_30cm', label: 'CE 30 cm', unit: 'dS/m', dec: 2, ico: 'onda', tono: 'suelo'},
    {key: 'eto', label: 'ETo', unit: 'mm', dec: 2, ico: 'sol', tono: 'clima'},
    {key: 'riego_acumulado_m3ha', label: 'Riego aplicado', unit: 'm³/ha', dec: 1, ico: 'brote', tono: 'agua'}]},
  meteo: {eyebrow: 'Estación meteorológica', ficha: [{label: 'Zona', key: 'zona'}, {label: 'SIGPAC', key: 'sigpac'}, {label: 'Cultivo', key: 'cultivo'}, {label: 'Superficie', key: 'hectareas', unit: 'ha', dec: 1}], kpis: [
    {key: 'agroan_coldhours', label: 'Horas de frío', unit: 'h', dec: 0, ico: 'frio', tono: 'agua'},
    {key: 'agroan_frozenhours', label: 'Horas de helada', unit: 'h', dec: 0, ico: 'frio', tono: 'clima'},
    {key: 'agroan_hothours', label: 'Horas de calor', unit: 'h', dec: 0, ico: 'sol', tono: 'temp'},
    {key: 'agroan_deltat', label: 'Delta T', unit: '°C', dec: 1, ico: 'delta', tono: 'temp'},
    {key: 'agroan_th', label: 'Integral térmica', unit: '°C·día', dec: 0, ico: 'curva', tono: 'suelo'}]},
  electrico: {eyebrow: 'Sensor eléctrico', titleFrom: 'label', ficha: [{label: 'Dispositivo', entity: 'name'}, {label: 'Batería', key: 'battery', src: 'ts', unit: 'V', dec: 2}, {label: 'Señal', key: 'signal', src: 'ts', dec: 0}], kpis: [
    {key: 'energia_importada_total_suma', label: 'Lectura', unit: 'kWh', dec: 0, ico: 'medidor', tono: 'energia'},
    {key: 'potencia_activa_total_raw', label: 'Potencia activa', unit: '', dec: 0, ico: 'rayo', tono: 'energia'},
    {key: 'factor_potencia_total', label: 'Factor de potencia', unit: '', dec: 3, ico: 'curva', tono: 'suelo'},
    {key: 'tension_L1_V', label: 'Tensión L1', unit: 'V', dec: 0, ico: 'onda', tono: 'agua'},
    {key: 'tension_L2_V', label: 'Tensión L2', unit: 'V', dec: 0, ico: 'onda', tono: 'agua'},
    {key: 'tension_L3_V', label: 'Tensión L3', unit: 'V', dec: 0, ico: 'onda', tono: 'agua'}]}
};

function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) { return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]; }); }
function fnum(n, d) {
  if (n == null || isNaN(n)) return '—';
  var neg = n < 0, s = Math.abs(n).toFixed(d).split('.');
  s[0] = s[0].replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  return (neg ? '−' : '') + s.join(',');
}
function toNum(v) { if (v == null || v === '') return null; var n = typeof v === 'number' ? v : parseFloat(String(v).replace(',', '.')); return isNaN(n) ? null : n; }
function midnight(t) { var d = new Date(t); d.setHours(0,0,0,0); return d.getTime(); }
function hhmm(t) { var d = new Date(t); return ('0' + d.getHours()).slice(-2) + ':' + ('0' + d.getMinutes()).slice(-2); }
function cuando(t) {
  if (!t) return '—';
  var hoy = midnight(Date.now());
  if (t >= hoy) return 'hoy, ' + hhmm(t);
  if (t >= hoy - DAY) return 'ayer, ' + hhmm(t);
  var d = new Date(t); return d.getDate() + ' ' + MES[d.getMonth()] + ' ' + d.getFullYear() + ', ' + hhmm(t);
}
function icon(name) { return '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' + (ICO[name] || ICO.curva) + '</svg>'; }

self.onInit = function () {
  var ctx = self.ctx;
  if (!document.getElementById('kv-fonts')) {
    var l = document.createElement('link'); l.id = 'kv-fonts'; l.rel = 'stylesheet';
    l.href = 'https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700&family=Mulish:wght@400;600;700;800&display=swap';
    document.head.appendChild(l);
  }
  var root = ctx.$container[0].querySelector('.kvh-root') || ctx.$container[0];
  var P = PERFILES[(ctx.settings || {}).perfil] || PERFILES.lisimetro;
  var ent = null, D = {attrs: {}, latest: {}, prev: {}, spark: {}};
  var api = self._kvh = {timer: null};

  function http(url) { return new Promise(function (res, rej) { ctx.http.get(url).subscribe(function (r) { res(r); }, function (e) { rej(e); }); }); }
  function tsUrl(keys, q) { return '/api/plugins/telemetry/' + ent.type + '/' + ent.id + '/values/timeseries?keys=' + encodeURIComponent(keys.join(',')) + q; }

  function load() {
    var attrKeys = P.ficha.filter(function (f) { return f.key && f.src !== 'ts'; }).map(function (f) { return f.key; });
    var tsKeys = P.kpis.map(function (k) { return k.key; }).concat(P.ficha.filter(function (f) { return f.src === 'ts'; }).map(function (f) { return f.key; }));
    var now = Date.now(), jobs = [];
    if (attrKeys.length) jobs.push(http('/api/plugins/telemetry/' + ent.type + '/' + ent.id + '/values/attributes?keys=' + encodeURIComponent(attrKeys.join(','))).then(function (r) {
      (r || []).forEach(function (a) { D.attrs[a.key] = a.value; });
    }).catch(function () {}));
    jobs.push(http(tsUrl(tsKeys, '')).then(function (r) {
      tsKeys.forEach(function (k) { var s = r && r[k] && r[k][0]; D.latest[k] = s ? {t: s.ts, v: s.value} : null; });
    }).catch(function () {}));
    jobs.push(http(tsUrl(tsKeys, '&startTs=' + (now - 2 * DAY) + '&endTs=' + (now - DAY) + '&agg=NONE&limit=1&orderBy=DESC')).then(function (r) {
      tsKeys.forEach(function (k) { var s = r && r[k] && r[k][0]; D.prev[k] = s ? toNum(s.value) : null; });
    }).catch(function () {}));
    jobs.push(http(tsUrl(P.kpis.map(function (k) { return k.key; }), '&startTs=' + (now - DAY) + '&endTs=' + now + '&agg=NONE&limit=2000&orderBy=ASC&useStrictDataTypes=true')).then(function (r) {
      P.kpis.forEach(function (k) {
        D.spark[k.key] = ((r && r[k.key]) || []).map(function (p) { return {t: p.ts, v: toNum(p.value)}; }).filter(function (p) { return p.v != null; });
      });
    }).catch(function () {}));
    return Promise.all(jobs);
  }

  function spark(pts, color) {
    if (!pts || pts.length < 2) return '';
    var t0 = pts[0].t, t1 = pts[pts.length - 1].t, mn = Infinity, mx = -Infinity;
    pts.forEach(function (p) { if (p.v < mn) mn = p.v; if (p.v > mx) mx = p.v; });
    if (mx === mn) { mx += 1; mn -= 1; }
    var W = 120, H = 34;
    var xy = pts.map(function (p) { return [(p.t - t0) / Math.max(1, t1 - t0) * W, 3 + (H - 6) * (1 - (p.v - mn) / (mx - mn))]; });
    var line = xy.map(function (q, i) { return (i ? 'L' : 'M') + q[0].toFixed(1) + ' ' + q[1].toFixed(1); }).join('');
    var area = line + 'L' + W + ' ' + H + 'L0 ' + H + 'Z';
    var last = xy[xy.length - 1];
    return '<svg class="kvh-spark" viewBox="0 0 120 34" preserveAspectRatio="none" role="img" aria-label="Últimas 24 horas">' +
      '<path d="' + area + '" fill="' + color + '" opacity=".10"/><path d="' + line + '" fill="none" stroke="' + color + '" stroke-width="1.75" vector-effect="non-scaling-stroke" stroke-linejoin="round"/>' +
      '</svg><span class="kvh-sdot" style="right:' + (100 - last[0] / W * 100).toFixed(1) + '%;top:' + (last[1] / H * 100).toFixed(1) + '%;background:' + color + '"></span>';
  }

  function render() {
    var title = ent ? (P.titleFrom === 'label' ? (ent.label || ent.name) : ent.name) : '—';
    var rows = P.ficha.map(function (f) {
      var v = f.entity ? (ent && ent[f.entity]) : (f.src === 'ts' ? (D.latest[f.key] && D.latest[f.key].v) : D.attrs[f.key]);
      var x = toNum(v), txt = v == null || v === '' ? '—' : (x != null && f.dec != null ? fnum(x, f.dec) : String(v)) + (f.unit && v != null && v !== '' ? ' ' + f.unit : '');
      return '<div class="kvh-row"><span class="kvh-rl">' + esc(f.label) + '</span><span class="kvh-rv">' + esc(txt) + '</span></div>';
    }).join('');
    var last = 0;
    Object.keys(D.latest).forEach(function (k) { var l = D.latest[k]; if (l && l.t > last) last = l.t; });
    var fresh = last && Date.now() - last < 6 * 3600000;
    var n = P.kpis.length, cols = n === 6 ? 3 : n, rowsN = n === 6 ? 2 : 1;
    var kpis = P.kpis.map(function (k) {
      var l = D.latest[k.key], v = l ? toNum(l.v) : null, p = D.prev[k.key], tono = TONO[k.tono] || TONO.agua, delta = '';
      if (v != null && p != null) {
        var d = v - p, eq = Math.abs(d) < Math.pow(10, -k.dec) / 2;
        delta = '<span class="kvh-delta ' + (eq ? 'eq' : (d > 0 ? 'up' : 'down')) + '">' + (eq ? '=' : (d > 0 ? '▲' : '▼')) + ' ' + fnum(Math.abs(d), k.dec) + '</span><span class="kvh-vs">vs ayer</span>';
      } else delta = '<span class="kvh-vs">Sin dato de ayer</span>';
      return '<div class="kvh-kpi"><div class="kvh-ktop"><span class="kvh-ico" style="background:' + tono[0] + ';color:' + tono[1] + '">' + icon(k.ico) + '</span>' +
        '<span class="kvh-kl">' + esc(k.label) + '</span></div>' +
        '<div class="kvh-kv">' + (v == null ? '—' : fnum(v, k.dec)) + (k.unit ? '<span class="kvh-ku">' + esc(k.unit) + '</span>' : '') + '</div>' +
        '<div class="kvh-kbot"><div class="kvh-kd">' + delta + '</div><div class="kvh-sp">' + spark(D.spark[k.key], tono[1]) + '</div></div></div>';
    }).join('');
    root.innerHTML = '<section class="kvh-ficha"><div class="kvh-fhead"><span class="kvh-eyebrow">' + esc(P.eyebrow) + '</span><h1 class="kvh-title">' + esc(title) + '</h1></div>' +
      '<div class="kvh-rows">' + rows + '</div>' +
      '<div class="kvh-last"><span class="kvh-ldot' + (fresh ? '' : ' old') + '"></span>Última lectura · ' + esc(cuando(last)) + '</div></section>' +
      '<section class="kvh-kpis' + (rowsN === 2 ? ' two' : '') + '" style="grid-template-columns:repeat(' + cols + ',minmax(0,1fr));grid-template-rows:repeat(' + rowsN + ',minmax(0,1fr))">' + kpis + '</section>';
    fit();
  }

  // Si el contenido no cabe en la altura del widget, se compacta automáticamente
  function fit() {
    var wrap = root.parentElement && root.parentElement.classList.contains('kvh-wrap') ? root.parentElement : root;
    wrap.classList.remove('dense', 'denser');
    var over = function () {
      return Array.prototype.some.call(root.querySelectorAll('.kvh-kpi,.kvh-ficha'), function (el) { return el.scrollHeight > el.clientHeight + 1; });
    };
    if (over()) { wrap.classList.add('dense'); if (over()) wrap.classList.add('denser'); }
  }
  api.fit = fit;

  function start() {
    var ds = (ctx.datasources && ctx.datasources[0]);
    var e = ds && ds.entityId ? {id: ds.entityId, type: ds.entityType, name: ds.entityName, label: ds.entityLabel} : null;
    if (!e) { ent = null; render(); return; }
    if (ent && ent.id === e.id) return;
    ent = e; D = {attrs: {}, latest: {}, prev: {}, spark: {}};
    render();
    load().then(render);
  }
  api.start = start;
  clearInterval(api.timer);
  api.timer = setInterval(function () { if (ent) load().then(render); }, 5 * 60 * 1000);
  start();
};

self.onDataUpdated = function () { if (self._kvh && self._kvh.start) self._kvh.start(); };
self.onResize = function () { if (self._kvh && self._kvh.fit) self._kvh.fit(); };
self.onDestroy = function () { if (self._kvh) clearInterval(self._kvh.timer); };
self.typeParameters = function () { return {maxDatasources: 1, maxDataKeys: 1, dataKeysOptional: true, singleEntity: true}; };
